def solve(coins, amount):
    # Unbounded coin change DP: minimize number of coins to make amount.
    # Edge cases
    if amount < 0:
        return -1
    # dp[i] = minimal coins for sum i, using inf for impossible.
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = float('inf')
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != float('inf') else -1

