def solve(nums):
    # patience sorting method O(n log n)
    import bisect
    tails = []
    for x in nums:
        # find insertion point in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

