def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D binary grid.
    Connectivity is 4-directional (up, down, left, right). Empty grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    if m == 0:
        return 0
    count = 0
    # Directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                count += 1
                # BFS to clear the island
                stack = [(i,j)]
                grid[i][j] = 0  # mark visited
                while stack:
                    x,y = stack.pop()
                    for dx,dy in dirs:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 1:
                            grid[nx][ny] = 0
                            stack.append((nx,ny))
    return count

def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find leftmost index where tails[idx] >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

