def solve(n: int, b: int) -> str:
    """Convert integer n to a string in base b (2 <= b <= 36).
    For bases outside this range, return an empty string.
    Uses digits 0-9 and lowercase a-z for values 10-35.
    Handles negative numbers with a leading '-'.
    """
    if b < 2 or b > 36:
        return ''
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, r = divmod(n, b)
        res.append(digits[r])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

