def solve(n, edges):
    """Return the lexicographically smallest topological order of a directed graph.
    If a cycle exists (including self‑loops or invalid edges), return an empty list.
    """
    from heapq import heappush, heappop
    # adjacency as sets to avoid duplicate edges
    adj = [set() for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        # ignore edges with out‑of‑range vertices
        if not (0 <= a < n and 0 <= b < n):
            continue
        if a == b:
            # self‑loop creates a cycle
            return []
        if b not in adj[a]:
            adj[a].add(b)
            indeg[b] += 1
    # min‑heap of nodes with indegree 0
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    # if not all nodes processed, there is a cycle
    if len(order) != n:
        return []
    return order

