def solve(n, edges):
    from heapq import heappush, heappop
    adj = [set() for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if not (0<=a<n and 0<=b<n):
            continue
        if a==b:
            return []
        if b not in adj[a]:
            adj[a].add(b)
            indeg[b]+=1
    heap=[]
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
    order=[]
    while heap:
        u=heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heappush(heap,v)
    if len(order)!=n:
        return []
    return order

